import { useEffect, useState } from "react";

type Post = { id: number; title: string };

type LoadState =
  | { status: "loading" }
  | { status: "success"; posts: Post[] }
  | { status: "error"; message: string };

function PostsPage() {
  const [state, setState] = useState<LoadState>({ status: "loading" });

  useEffect(() => {
    const controller = new AbortController();
    setState({ status: "loading" });

    async function load() {
      try {
        const response = await fetch("https://jsonplaceholder.typicode.com/posts", {
          signal: controller.signal,
        });
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        const posts = (await response.json()) as Post[];
        setState({ status: "success", posts: posts.slice(0, 10) });
      } catch (error) {
        if (controller.signal.aborted) return;
        setState({ status: "error", message: "Не удалось загрузить посты" });
      }
    }

    void load();
    return () => controller.abort();
  }, []);

  if (state.status === "loading") return <p>Загрузка постов…</p>;
  if (state.status === "error") return <p role="alert">{state.message}</p>;
  if (state.posts.length === 0) return <p>Пока нет постов.</p>;
  return <PostList posts={state.posts} />;
}

