import { useEffect, useRef } from 'react';

function ChartPanel({ createChart }: { createChart: (host: HTMLDivElement) => { destroy: () => void } }) {
  const hostRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const host = hostRef.current;
    if (!host) return;

    const chart = createChart(host);
    return () => chart.destroy();
  }, [createChart]);

  return <div ref={hostRef} role="region" aria-label="Встроенный график" />;
}

import { useEffect } from 'react';

const THEME_KEY = 'guide-theme';

function useThemeFromOtherTabs(setTheme: (value: 'light' | 'dark') => void) {
  useEffect(() => {
    function handleStorage(event: StorageEvent) {
      if (event.key !== THEME_KEY) return;
      if (event.newValue === 'light' || event.newValue === 'dark') {
        setTheme(event.newValue);
      }
    }

    window.addEventListener('storage', handleStorage);
    return () => window.removeEventListener('storage', handleStorage);
  }, [setTheme]);
}

